```json
{
  "pasos": [
    {
      "id": "s1",
      "op": "search_catalog",
      "args": {
        "category": "televisores",
        "max_price": 1104990,
        "limit": 5
      }
    },
    {
      "id": "s2",
      "op": "get_reviews",
      "args": {
        "product_id": "$s1.0.id",
        "limit": 3
      }
    },
    {
      "id": "s3",
      "op": "get_product",
      "args": {
        "id": "$s1.1.id"
      }
    },
    {
      "id": "s4",
      "op": "compare_products",
      "args": {
        "ids": ["$s1.0.id", "$s1.1.id"]
      }
    },
    {
      "id": "s5",
      "op": "respond",
      "plantilla": "Encontré {cantidad} opciones de televisores dentro de tu presupuesto de $1.104.990.\n\nMi recomendación principal es {nombre1} <<rec:{id1}>> a ${precio1}, con evaluación de {rating1} estrellas. {resumen_reviews}\n\nOtra opción es {nombre2} <<rec:{id2}>> a ${precio2}.\n\nComparación: <<cmp:{id1},{id2}>>. El más barato es {mas_barato} y el mejor evaluado es {mejor_evaluado}.",
      "vars": {
        "cantidad": 5,
        "nombre1": "$s1.0.name",
        "id1": "$s1.0.id",
        "precio1": "$s1.0.price_clp",
        "rating1": "$s1.0.avg_rating",
        "resumen_reviews": "$s2",
        "nombre2": "$s3.name",
        "id2": "$s3.id",
        "precio2": "$s3.price_clp",
        "mas_barato": "$s4.mas_barato",
        "mejor_evaluado": "$s4.mejor_evaluado"
      }
    }
  ]
}
